class Solution:
    def maxSatisfied(self, customers, grumpy, X):
        result, max_extra, extra = 0, 0, 0
        for i in range(len(customers)):
            result += 0 if grumpy[i] else customers[i]
            extra += customers[i] if grumpy[i] else 0
            if i >= X:
                extra -= customers[i-X] if grumpy[i-X] else 0
            max_extra = max(max_extra, extra)
        return result + max_extra

class Solution:
    def prevPermOpt1(self, A):
        for left in reversed(range(len(A)-1)):
            if A[left] > A[left+1]:
                break
        else:
            return A
        right = len(A)-1
        while A[left] <= A[right]:
            right -= 1
        while A[right-1] == A[right]:
            right -= 1
        A[left], A[right] = A[right], A[left]
        return A

class Solution:
    def gcdOfStrings(self, str1: str, str2: str) -> str:

        if len(str2) > len(str1):
            str1, str2 = str2, str1

        curr_str2 = str2
        while True:

            rep = len(str1)//len(curr_str2)

            if curr_str2*rep == str1:
                return curr_str2

            found = False
            for i in range(len(curr_str2)-1, 1, -1):
                try_str2 = curr_str2[:i]
                rep2 = len(str2)//len(try_str2)

                if try_str2*rep2 == str2:
                    curr_str2 = try_str2
                    found = True
                    break

            if not found:
                break
        return ""

class Solution:
    def gcdOfStrings(self, str1: str, str2: str) -> str:
        def check(s, common):
            i = 0
            for c in s:
                if c != common[i]:
                    return False
                i = (i+1)%len(common)
            return True

        def gcd(a, b):  # Time: O(log(min(a, b)))
            while b:
                a, b = b, a % b
            return a

        if not str1 or not str2:
            return ""
        c = gcd(len(str1), len(str2))
        result = str1[:c]
        return result if check(str1, result) and check(str2, result) else ""

