class Solution:
    def smallestSubsequence(self, s: str) -> str:
         # calculate the last occurence of each characters in s
        last_occurence = {c: i for i, c in enumerate(s)}

        stack = []
        # check if element is in stack
        instack = set()
        for i, c in enumerate(s):
            if c not in instack:
                # check if stack already have char larger then current char
                # and if char in stack will occur later again, remove that from stack
                while stack and stack[-1] > c and last_occurence[stack[-1]] > i:
                    instack.remove(stack[-1])
                    stack.pop()

                instack.add(c)   
                stack.append(c)

        return "".join(stack)

import collections

class Solution:
    def smallestSubsequence(self, text):
        count = collections.Counter(text)

        lookup, stk = set(), []
        for c in text:
            if c not in lookup:
                while stk and stk[-1] > c and count[stk[-1]]:
                    lookup.remove(stk.pop())
                stk += c
                lookup.add(c)
            count[c] -= 1
        return "".join(stk)

class Solution:
    def shortestCommonSupersequence(self, A, B):
        n, m = len(A), len(B)
        dp = [B[:i] for i in range(m + 1)]
        for i in range(n):
            prev = A[:i]
            dp[0] = A[:i + 1]
            for j in range(m):
                if A[i] == B[j]:
                    prev, dp[j + 1] = dp[j + 1], prev + A[i]
                else:
                    prev, dp[j + 1] = dp[j + 1], min(dp[j] + B[j], dp[j + 1] + A[i], key = len)
        return dp[-1]
